const produtos = $('Buscar Produtos \'Encontrado\'').all();
const settingsList = $('Buscar Regras de Filtro (Settings)').all().map(s => s.json);

// Indexa configurações por categoria com fallback padrão
const settingsMap = {};
for (const s of settingsList) {
  settingsMap[s.categoria.toLowerCase()] = s;
}

const defaultSetting = {
  desconto_minimo: 30.0,
  avaliacao_minima: 4.5,
  vendas_minimas: 100,
  preco_maximo: 800.0
};

const resultados = [];

for (const p of produtos) {
  const item = p.json;
  const catLower = (item.categoria || '').toLowerCase();
  const cfg = settingsMap[catLower] || defaultSetting;

  const preco = parseFloat(item.preco || 0);
  const desconto = parseFloat(item.desconto || 0);
  const avaliacao = parseFloat(item.avaliacao || 0);
  const vendas = parseInt(item.vendas || 0, 10);
  const imagem = (item.imagem || '').trim();

  let status = 'aprovado';
  let motivo = '';

  // Validações de integridade e qualidade
  if (!imagem || imagem.length < 10) {
    status = 'rejeitado';
    motivo = 'Sem imagem válida';
  } else if (desconto < parseFloat(cfg.desconto_minimo)) {
    status = 'rejeitado';
    motivo = `Desconto (${desconto}%) menor que mínimo (${cfg.desconto_minimo}%)`;
  } else if (avaliacao < parseFloat(cfg.avaliacao_minima)) {
    status = 'rejeitado';
    motivo = `Avaliação (${avaliacao}⭐) menor que mínima (${cfg.avaliacao_minima}⭐)`;
  } else if (vendas < parseInt(cfg.vendas_minimas, 10)) {
    status = 'rejeitado';
    motivo = `Vendas (${vendas}) menor que mínimo (${cfg.vendas_minimas})`;
  } else if (preco > parseFloat(cfg.preco_maximo)) {
    status = 'rejeitado';
    motivo = `Preço (R$ ${preco}) maior que teto permitido (R$ ${cfg.preco_maximo})`;
  }

  // Cálculo da Pontuação Ponderada (0 a 100 pontos)
  // 1. Desconto: até 40 pontos (40% de peso)
  const scoreDesconto = Math.min((desconto / 70) * 40, 40);

  // 2. Avaliação: até 30 pontos (30% de peso) - Escala de 4.0 a 5.0 estrelas
  const scoreAvaliacao = Math.max(0, Math.min(((avaliacao - 4.0) / 1.0) * 30, 30));

  // 3. Vendas: até 20 pontos (20% de peso) - Teto em 1000 vendas para pontuação máxima
  const scoreVendas = Math.min((vendas / 1000) * 20, 20);

  // 4. Preço acessível/ticket ideal: até 10 pontos (10% de peso)
  let scorePreco = 5;
  if (preco > 0 && preco <= 150) scorePreco = 10;
  else if (preco <= 350) scorePreco = 8;
  else if (preco <= 600) scorePreco = 6;

  const scoreTotal = parseFloat((scoreDesconto + scoreAvaliacao + scoreVendas + scorePreco).toFixed(2));

  resultados.push({
    json: {
      id: item.id,
      shopee_item_id: item.shopee_item_id,
      nome: item.nome,
      status: status,
      score: scoreTotal,
      motivo_rejeicao: motivo,
      categoria: item.categoria,
      preco: preco,
      desconto: desconto
    }
  });
}

// Ordena aprovados primeiro pelo maior score
resultados.sort((a, b) => b.json.score - a.json.score);

return resultados;

